-- Справочник городов: единственный источник правды для профиля, фильтра каталога и клуба.
-- До этой миграции город клуба был свободным текстом, и клуб в «мск» не находился фильтром
-- «Москва» никогда — точное сравнение строк в JooqClubRepository.findAll.
-- Данные: выгрузка GeoNames (cities15000, порог населения 50 000, страны RU/BY/KZ/AM/GE/AE/TR),
-- русские имена по языковой метке ru. Спека: docs/modules/city-dictionary.md.

CREATE TABLE IF NOT EXISTS cities (
    id              UUID PRIMARY KEY,
    country_code    VARCHAR(2)   NOT NULL,
    name            VARCHAR(120) NOT NULL,
    normalized_name VARCHAR(120) NOT NULL,
    region          VARCHAR(120),
    needs_region    BOOLEAN      NOT NULL DEFAULT FALSE,
    population      INTEGER      NOT NULL,
    latitude        NUMERIC(9,6) NOT NULL,
    longitude       NUMERIC(9,6) NOT NULL,
    geoname_id      INTEGER      NOT NULL,
    is_featured     BOOLEAN      NOT NULL DEFAULT FALSE
);

COMMENT ON TABLE cities IS
    'Справочник городов (GeoNames, население от 50 000). Пополняется только новой миграцией — '
    'пользователи города не заводят.';
COMMENT ON COLUMN cities.country_code IS 'Код страны ISO 3166-1 alpha-2 («RU»), совпадает по формату с users.country.';
COMMENT ON COLUMN cities.name IS 'Русское название города для показа («Балашиха»). Без области и прочих уточнений.';
COMMENT ON COLUMN cities.normalized_name IS
    'Ключ поиска и дедупликации: lower + ё→е + trim + схлопывание пробелов. Дефис СОХРАНЁН '
    '(«Ростов-на-Дону» ≠ «Ростов»).';
COMMENT ON COLUMN cities.region IS 'Регион («Курская область») — показывается только при needs_region. NULL = регион неизвестен.';
COMMENT ON COLUMN cities.needs_region IS
    'TRUE = у города есть тёзка в другом регионе той же страны (Железногорск, Эрегли), '
    'и без региона его не отличить. FALSE = имя уникально, регион не показываем.';
COMMENT ON COLUMN cities.population IS 'Население, человек. Используется для сортировки выдачи, порог отбора — 50 000.';
COMMENT ON COLUMN cities.latitude IS 'Широта центра города, градусы. Заложено под будущее «клубы рядом», UI пока не использует.';
COMMENT ON COLUMN cities.longitude IS 'Долгота центра города, градусы.';
COMMENT ON COLUMN cities.geoname_id IS 'Идентификатор объекта в GeoNames — связь с источником для пересборки сида.';
COMMENT ON COLUMN cities.is_featured IS
    'TRUE = показывать в пикере до ввода запроса (витрина). Поиск идёт по ВСЕМУ справочнику '
    'независимо от этого флага.';

-- Регион входит в ключ намеренно: тёзки из РАЗНЫХ регионов — настоящие разные города
-- (Железногорск в Курской области и в Красноярском крае, Эрегли в Конье и Зонгулдаке), и они
-- обязаны сосуществовать. Дубль внутри одного региона по-прежнему невозможен.
-- COALESCE нужен потому, что в уникальном индексе NULL не равен NULL, и города без региона
-- иначе задваивались бы свободно.
CREATE UNIQUE INDEX IF NOT EXISTS idx_cities_country_normalized
    ON cities(country_code, normalized_name, COALESCE(region, ''));
CREATE INDEX IF NOT EXISTS idx_cities_featured ON cities(is_featured) WHERE is_featured;

