-- Город клуба и пользователя: FK на справочник. NULLABLE намеренно — легаси-клуб с нераспознанным
-- городом не должен упасть, он попросит организатора уточнить город при следующем входе.
ALTER TABLE clubs ADD COLUMN IF NOT EXISTS city_id UUID REFERENCES cities(id);
ALTER TABLE users ADD COLUMN IF NOT EXISTS city_id UUID REFERENCES cities(id);

COMMENT ON COLUMN clubs.city_id IS
    'Город клуба из справочника cities. NULL = легаси-запись, город которой не удалось распознать; '
    'такой клуб не находится фильтром каталога, пока организатор не уточнит город.';
COMMENT ON COLUMN users.city_id IS 'Город пользователя из справочника cities (NULL = не указан).';

CREATE INDEX IF NOT EXISTS idx_clubs_city_id ON clubs(city_id);

-- Бэкфилл легаси-текста. Нормализация ловит регистр, лишние пробелы и ё/е: «москва », «МОСКВА»,
-- «Королев» → сматчатся. Сокращения и опечатки («мск», «Санкт Петербург» без дефиса) — НЕ
-- сматчатся и останутся с city_id IS NULL: их уточняет организатор из управления клубом.
-- Текст города перезаписывается каноническим написанием только при совпадении; иначе остаётся
-- как был, чтобы организатор видел, что он вводил. При тёзках в разных странах берём крупнейший.
UPDATE clubs c
SET city_id = m.id, city = m.name
FROM (
    SELECT DISTINCT ON (normalized_name) normalized_name, id, name
    FROM cities ORDER BY normalized_name, population DESC
) m
WHERE c.city_id IS NULL
  AND regexp_replace(btrim(translate(lower(c.city), 'ё', 'е')), '\s+', ' ', 'g')
      = m.normalized_name;

UPDATE users u
SET city_id = m.id, city = m.name
FROM (
    SELECT DISTINCT ON (normalized_name) normalized_name, id, name
    FROM cities ORDER BY normalized_name, population DESC
) m
WHERE u.city_id IS NULL AND u.city IS NOT NULL
  AND regexp_replace(btrim(translate(lower(u.city), 'ё', 'е')), '\s+', ' ', 'g')
      = m.normalized_name;
